'use strict';
/* Opt-in proof of concept layered over the unmodified game content and combat rules. */
const POC={mode:'refined',lastPlace:null,lastWalk:false};
try{POC.mode=localStorage.getItem('pb-poc-look')==='original'?'original':'refined'}catch(e){}
function pocActive(){return POC.mode==='refined'}
function pocApply(){document.documentElement.dataset.poc=POC.mode;const el=document.getElementById('poc-toggle');if(el)el.textContent='Prototype · '+(pocActive()?'Refined':'Original');document.body.classList.remove('poc-walking');if(typeof MAP!=='undefined')MAP.dirty=true}
pocApply();
/* Keep scene palettes, geometry, weather and gameplay intact. Only cap distracting post effects. */
const pocBaseEng=eng;
eng=function(group,key){const v=pocBaseEng(group,key);if(!pocActive()||ENG_CTX.bypass)return v;
 const caps={lens:{blur:.16,blurNear:.25,aberration:0,grain:0,vignette:.16},color:{bloom:.24},world:{groundShine:.45,texDetail:.7},camera:{sway:.3}};
 const cap=caps[group]&&caps[group][key];return typeof cap==='number'&&typeof v==='number'?Math.min(v,cap):v};
function pocSet(mode){POC.mode=mode;try{localStorage.setItem('pb-poc-look',mode)}catch(e){}pocApply();if(U.modal&&U.modal.poc){U.modal.html=pocMenuHTML();renderOv()}else if(!B)render();if(B)paintActions();pocRefresh();}
function pocMenuHTML(){return `<p class="poc-intro">This is the actual <b>Pocket Billies alpha 0.5</b> game, with its original world, art, story and battle engine. Compare a focused UI and graphics pass without changing your progress.</p><div class="poc-options"><button data-poc="refined" aria-pressed="${pocActive()}">Refined<small>Clear text, quieter panels, less blur, readable battle effects.</small></button><button data-poc="original" aria-pressed="${!pocActive()}">Original alpha 0.5<small>The original interface and renderer settings, on the same scene.</small></button></div><div class="poc-options"><button data-poc="graphics">Graphics settings<small>Use the existing presets and interactive graphics gallery.</small></button><button data-poc="help">What to try<small>Explore, battle, tax a Billie, and inspect its growth.</small></button></div><p class="poc-source">Source: <a href="https://github.com/nojiroh/pocket-billies/tree/d6b8441f02bbf588090f120f3273501b9d202f02" target="_blank" rel="noopener">nojiroh/pocket-billies · d6b8441</a>. This prototype has a separate browser save. Cloud accounts are disabled in this copy.</p>`}
function pocMenu(){if(B&&B.phase==='playing'){toast('Finish this animation before opening the comparison.');return}modal({title:'Pocket Billies · prototype',poc:true,html:pocMenuHTML(),btns:[{l:'Back to the game',c:'dark',f:closeModal}]})}
function pocHelp(){modal({title:'Try the improvements',html:`<div class="poc-intro"><p><b>1. Explore:</b> use WASD/arrows, the joystick, or tap the ground. The location card fades while you move. “Next up” gives a relevant action.</p><p><b>2. Compare:</b> use the Prototype button to switch the original and refined look on the same world. The refined pass reduces blur, grain and glare while retaining the original art.</p><p><b>3. Battle:</b> pick a wild encounter. Move descriptions stay visible; status and Alpha shield details appear above the controls. Tax odds still use the original engine.</p><p><b>4. Grow:</b> open Team → a Billie → Evolves. Split evolutions show the actual Build/Hype balance.</p><p><b>5. Tune:</b> use Settings → Graphics to test the existing quality presets and gallery.</p><p>This pass does not replace artwork, rewrite loading, or implement cloud-save conflict handling.</p></div>`,btns:[{l:'Let’s play',c:'dark',f:closeModal}]})}
function pocQuickStart(){if(S.started){titleEnd();render();return}titleEnd();const starters=(RULES.start.starters||[]).filter(l=>SP[l+'0']);modal({title:'Choose your first Billie',html:`<p class="poc-intro">Jump into Copperleaf with the real game’s starter, encounters, items and progression. The full original opening remains available with New game.</p><div class="poc-options">${starters.map(l=>`<button data-poc="starter" data-line="${l}">${bustHTML(l+'0',64)}<b>${esc(SP[l+'0'].name)}</b><small>${SP[l+'0'].types.map(esc).join(' / ')}</small></button>`).join('')}</div>`,btns:[{l:'Back',c:'quiet',f:()=>{closeModal();titleStart();render()}}]})}
const pocTitle=renderTitle;
renderTitle=function(){return pocTitle()+(!S.started?'<div class="poc-quick" style="position:fixed;bottom:16px;left:50%;transform:translateX(-50%);z-index:30"><button class="pb dark" data-poc="quick">Try prototype · skip opening</button></div>':'')};
function pocNext(){if(!S.started)return null;const r=ROUTE[S.route.node];if(!r)return null;if(S.team.some(m=>m.hp<=0)&&r.town)return{title:'Rest your team at the clinic',sub:'Free healing before your next encounter',a:'clinic'};
 const block=blockerAt(S.route.node);if(block)return{title:'Challenge '+block.name,sub:'This trainer is blocking the next route',a:'trainer',t:block.id};
 if(S.queue.length)return{title:Object.keys(S.caught).length<2?'Tax your first wild Billie':'A Billie is rustling nearby',sub:'Weaken it, then choose Tax it',a:'enc',id:S.queue[0].id};
 return{title:'Explore '+r.name,sub:'Tap people and doors, or choose your next route',a:'tab',t:'map'}}
function pocRefresh(){let b=document.getElementById('poc-toggle');if(!b){b=document.createElement('button');b.id='poc-toggle';b.type='button';b.onclick=pocMenu;document.body.appendChild(b);pocApply()}
 b.hidden=!!(U.title===false&&!S.started)||!!(typeof CS!=='undefined'&&CS.on)||!!(typeof STEST!=='undefined'&&STEST.on);
 let n=document.getElementById('poc-next');const show=pocActive()&&S.started&&!B&&U.tab==='walk'&&!U.title&&!U.modal&&!U.inside&&!U.bench&&!(typeof CS!=='undefined'&&CS.on)&&!(typeof TALK!=='undefined'&&TALK.on);
 if(!show){if(n)n.hidden=true;return}if(!n){n=document.createElement('button');n.id='poc-next';n.className='poc-next';document.body.appendChild(n)}n.hidden=false;
 const v=pocNext();if(v){n.innerHTML=`<small>NEXT UP</small><b>${esc(v.title)}</b><em>${esc(v.sub)} →</em>`;n.onclick=()=>{if(v.a==='clinic'){document.querySelector('[data-a="clinic"]')?.click();if(!document.querySelector('[data-a="clinic"]')){U.modal=null;modal({title:'The clinic',html:'<p>Open Actions to find the clinic, or tap its door in town.</p>',btns:[{l:'Open Actions',c:'dark',f:()=>{closeModal();document.querySelector('[data-a="walkdown"]')?.click()}}]})}}else if(v.a==='enc'){const q=S.queue.find(q=>q.id===v.id);if(q)startWild(q)}else if(v.a==='trainer')trainerTalk(v.t);else{U.tab='map';render()}}}}
const pocPaint=paintActions;
paintActions=function(){pocPaint();if(!pocActive()||!B)return;const el=document.getElementById('acts');if(!el)return;
 el.querySelectorAll('.mv[data-m]').forEach(b=>{const m=MOVES[b.dataset.m];if(m&&m.d){const s=document.createElement('span');s.className='poc-move-copy';s.textContent=m.d;b.appendChild(s)}});
 const notes=[];for(const k of liveK()){const m=A(k),v=FV(k);if(m.status)notes.push(`${N(m)}: ${STATUSN[m.status]||m.status}`);if(v.shield>0)notes.push(`${N(m)} · shield: ${v.shield} turn${v.shield===1?'':'s'}`);if(v.hyped>0)notes.push(`${N(m)} · confused: ${v.hyped} turns`)}
 let html=notes.map(s=>`<span>${esc(s)}</span>`).join('');if(B.integrity>1)html+=`<span class="focus">Focus ×${+B.integrity.toFixed(2)} · next tax</span>`;if(html)el.insertAdjacentHTML('afterbegin',`<div class="poc-battle-notes" role="status">${html}</div>`);
 if(B.phase==='coins')el.insertAdjacentHTML('afterbegin','<div class="poc-tax-note">Lower HP and status effects improve your odds. These estimates assume an average throw; timing and spin affect the result.</div>');
 if(B.phase==='target')el.insertAdjacentHTML('afterbegin','<div class="poc-tax-note">Choose the highlighted opponent this move should hit.</div>');};
function pocGrowthHTML(m){const s=SP[m.sp],e=s&&s.evo;if(!e||e.k!=='split')return '';const build=((m.bsteps||0)+(m.psteps||0)/2)/STEPS_PER_KM,hype=m.wins||0,total=build+hype,share=total?build/total:0;
 return `<section class="poc-growth"><h3>Build or Hype?</h3><p><b>${splitPath(m)==='A'?'Build':'Hype'}</b> currently leads. Evolves at level ${e.at}.</p><div class="poc-growth-track" aria-label="Build ${build.toFixed(1)} points, Hype ${hype} points"><i style="width:${share*100}%"></i><b style="width:${total?(1-share)*100:0}%"></b></div><p>Build <b>${build.toFixed(1)}</b> · Hype <b>${hype}</b></p><p>One buddy kilometre equals one battle win. Party distance counts at half weight. A tie follows Build.</p></section>`}
const pocMonSheet=monSheet;
monSheet=function(m){pocMonSheet(m);if(!pocActive()||!U.modal)return;const html=pocGrowthHTML(m);if(html){U.modal.html=U.modal.html.replace('<div class="ms-pane" data-k="evo" hidden>','<div class="ms-pane" data-k="evo" hidden>'+html);renderOv()}};
/* Existing frame scheduler: no second render loop. Low-frequency DOM state updates only. */
frameTask('prototype-ui',()=>{const walking=pocActive()&&S.started&&!B&&U.tab==='walk'&&!U.modal&&DIO.pl&&DIO.pl.walk;if(!!walking!==POC.lastWalk){POC.lastWalk=!!walking;document.body.classList.toggle('poc-walking',!!walking)}pocRefresh()},4);
document.addEventListener('click',e=>{const b=e.target.closest&&e.target.closest('[data-poc]');if(!b||b===document.documentElement)return;const a=b.dataset.poc;if(!a)return;e.preventDefault();e.stopPropagation();
 if(a==='original'||a==='refined')pocSet(a);else if(a==='quick')pocQuickStart();else if(a==='starter'){const l=b.dataset.line;if(!RULES.start.starters.includes(l))return;closeModal();startGame(l);applyPreferences();pocRefresh()}else if(a==='graphics'){closeModal();settings('graphics')}else if(a==='help'){closeModal();pocHelp()}},true);
